pub struct Document {
    pub id: u64,
    pub title: String,
    pub pages: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ArchiveError {
    ZeroId,
    EmptyTitle,
    ZeroPages,
    DuplicateId,
    NotFound,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Archive {
    documents: Vec<Document>,
}

impl Document {
    pub fn new(id: u64, title: impl Into<String>, pages: u32) -> Result<Self, ArchiveError> {
        let title = title.into();
        if id == 0 {
            return Err(ArchiveError::ZeroId);
        }
        if title.trim_matches(|c: char| c.is_ascii_whitespace()).is_empty() {
            return Err(ArchiveError::EmptyTitle);
        }
        if pages == 0 {
            return Err(ArchiveError::ZeroPages);
        }
        Ok(Self { id, title, pages })
    }
}

impl Archive {
    pub fn new() -> Self {
        Self { documents: Vec::new() }
    }

    pub fn add(&mut self, document: Document) -> Result<(), ArchiveError> {
        if self.documents.iter().any(|stored| stored.id == document.id) {
            return Err(ArchiveError::DuplicateId);
        }
        self.documents.push(document);
        Ok(())
    }

    pub fn remove(&mut self, id: u64) -> Result<Document, ArchiveError> {
        let index = self.documents.iter().position(|document| document.id == id)
            .ok_or(ArchiveError::NotFound)?;
        Ok(self.documents.swap_remove(index))
    }

    pub fn get(&self, id: u64) -> Option<&Document> {
        self.documents.iter().find(|document| document.id == id)
    }

    pub fn documents(&self) -> &[Document] {
        &self.documents
    }

    pub fn total_pages(&self) -> u64 {
        self.documents.iter().map(|document| u64::from(document.pages)).sum()
    }
}

