#[path = "solution.rs"]
mod solution;

use solution::{Archive, ArchiveError, Document};

fn document(id: u64, title: &str, pages: u32) -> Document {
    match Document::new(id, title, pages) { Ok(v) => v, Err(_) => panic!("unexpected document error") }
}

#[test]
fn document_validation_preserves_valid_title_exactly() {
    assert!(matches!(Document::new(0, "title", 1), Err(ArchiveError::ZeroId)));
    assert!(matches!(Document::new(1, "", 1), Err(ArchiveError::EmptyTitle)));
    assert!(matches!(Document::new(1, " \t\r\n", 1), Err(ArchiveError::EmptyTitle)));
    assert!(matches!(Document::new(1, "title", 0), Err(ArchiveError::ZeroPages)));

    let doc = document(7, "  preserved title  ", 2);
    assert_eq!(doc.title, "  preserved title  ");
    let unicode_space = document(8, "\u{2003}", 1);
    assert_eq!(unicode_space.title, "\u{2003}");
}

#[test]
fn empty_archive_views_are_valid() {
    let archive = Archive::new();
    assert!(archive.documents().is_empty());
    assert!(archive.get(1).is_none());
    assert_eq!(archive.total_pages(), 0);
}

#[test]
fn add_get_and_documents_preserve_insertion_order() {
    let mut archive = Archive::new();
    assert!(archive.add(document(20, "twenty", 3)).is_ok());
    assert!(archive.add(document(10, "ten", 4)).is_ok());
    assert_eq!(archive.documents().iter().map(|d| d.id).collect::<Vec<_>>(), vec![20, 10]);
    assert_eq!(archive.get(10).map(|d| d.title.as_str()), Some("ten"));
    assert_eq!(archive.total_pages(), 7);
}

#[test]
fn duplicate_add_does_not_mutate_archive() {
    let mut archive = Archive::new();
    archive.add(document(1, "original", 5)).unwrap_or_else(|_| panic!("unexpected error"));
    assert!(matches!(archive.add(document(1, "replacement", 99)), Err(ArchiveError::DuplicateId)));
    assert_eq!(archive.documents().len(), 1);
    assert_eq!(archive.documents()[0].title, "original");
    assert_eq!(archive.total_pages(), 5);
}

#[test]
fn removal_returns_document_and_preserves_relative_order() {
    let mut archive = Archive::new();
    for (id, title) in [(1, "a"), (2, "b"), (3, "c"), (4, "d")] {
        archive.add(document(id, title, id as u32)).unwrap_or_else(|_| panic!("unexpected error"));
    }
    let removed = match archive.remove(2) { Ok(v) => v, Err(_) => panic!("unexpected removal error") };
    assert_eq!((removed.id, removed.title.as_str(), removed.pages), (2, "b", 2));
    assert_eq!(archive.documents().iter().map(|d| d.id).collect::<Vec<_>>(), vec![1, 3, 4]);
    assert!(archive.get(2).is_none());
    assert_eq!(archive.total_pages(), 8);
}

#[test]
fn missing_removal_is_non_mutating() {
    let mut archive = Archive::new();
    archive.add(document(1, "one", 7)).unwrap_or_else(|_| panic!("unexpected error"));
    assert!(matches!(archive.remove(999), Err(ArchiveError::NotFound)));
    assert_eq!(archive.documents().len(), 1);
    assert_eq!(archive.documents()[0].id, 1);
    assert_eq!(archive.total_pages(), 7);
}

#[test]
fn total_pages_uses_u64_arithmetic() {
    let mut archive = Archive::new();
    archive.add(document(1, "first", u32::MAX)).unwrap_or_else(|_| panic!("unexpected error"));
    archive.add(document(2, "second", u32::MAX)).unwrap_or_else(|_| panic!("unexpected error"));
    assert_eq!(archive.total_pages(), 2 * u64::from(u32::MAX));
    assert_eq!(archive.documents().len(), 2);
}

